llm_calls.response:
def check(candidate):
    s = "aAa"
    result = candidate(s)

    expected = set()
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            sub = s[i:j]
            if sub == sub[::-1]:
                expected.add(sub)
    expected = sorted(expected)

    assert result == expected
    assert result == sorted(result)
    assert len(result) == len(set(result))

